    "title": "Custom Rigid Boxes: Construction, Specifications and Ordering",
    "category": "Sourcing Guide",
    "date": "October 2026",
    "readTime": "8 min read",
    "image": "/images/covers/custom-rigid-boxes-guide-reviewed.png",
